create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text not null default '聯大新朋友',avatar text not null default '🧑🏻‍🎓',created_at timestamptz not null default now());
create table if not exists public.restaurants(id uuid primary key default gen_random_uuid(),name text not null,description text,address text,phone text,is_active boolean not null default true,owner_id uuid references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.menu_items(id uuid primary key default gen_random_uuid(),restaurant_id uuid not null references public.restaurants(id) on delete cascade,name text not null,description text,price integer not null check(price>=0),is_available boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.orders(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),restaurant_id uuid not null references public.restaurants(id),status text not null default 'pending' check(status in('pending','accepted','preparing','ready','completed','cancelled')),total_amount integer not null check(total_amount>=0),note text,payment_method text not null default 'pay_at_pickup',created_at timestamptz not null default now());
create table if not exists public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,menu_item_id uuid not null references public.menu_items(id),item_name text not null,unit_price integer not null check(unit_price>=0),quantity integer not null check(quantity between 1 and 30));
create table if not exists public.chat_messages(id uuid primary key default gen_random_uuid(),room text not null default 'campus',user_id uuid not null references auth.users(id),display_name text not null,body text not null check(char_length(body) between 1 and 240),created_at timestamptz not null default now());
alter table public.profiles enable row level security;alter table public.restaurants enable row level security;alter table public.menu_items enable row level security;alter table public.orders enable row level security;alter table public.order_items enable row level security;alter table public.chat_messages enable row level security;
create policy "profile read" on public.profiles for select to authenticated using(true);create policy "profile own insert" on public.profiles for insert to authenticated with check(auth.uid()=id);create policy "profile own update" on public.profiles for update to authenticated using(auth.uid()=id) with check(auth.uid()=id);
create policy "active restaurant read" on public.restaurants for select using(is_active);create policy "available menu read" on public.menu_items for select using(is_available);
create policy "customer own orders" on public.orders for select to authenticated using(auth.uid()=user_id);create policy "merchant own orders" on public.orders for select to authenticated using(exists(select 1 from public.restaurants r where r.id=restaurant_id and r.owner_id=auth.uid()));
create policy "customer own order items" on public.order_items for select to authenticated using(exists(select 1 from public.orders o where o.id=order_id and o.user_id=auth.uid()));create policy "merchant own order items" on public.order_items for select to authenticated using(exists(select 1 from public.orders o join public.restaurants r on r.id=o.restaurant_id where o.id=order_id and r.owner_id=auth.uid()));
create policy "authenticated chat read" on public.chat_messages for select to authenticated using(true);create policy "authenticated chat send self" on public.chat_messages for insert to authenticated with check(auth.uid()=user_id);
create or replace function public.create_order(p_restaurant_id uuid,p_items jsonb,p_note text default '') returns uuid language plpgsql security definer set search_path=public as $$declare v_user uuid:=auth.uid();v_order uuid;v_total integer:=0;v_item jsonb;v_menu public.menu_items%rowtype;v_qty integer;begin
 if v_user is null then raise exception '請先登入會員';end if;if length(coalesce(p_note,''))>300 then raise exception '備註不可超過 300 字';end if;if jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items)=0 then raise exception '購物車是空的';end if;if not exists(select 1 from public.restaurants where id=p_restaurant_id and is_active) then raise exception '店家目前未營業或不存在';end if;
 for v_item in select * from jsonb_array_elements(p_items) loop v_qty:=(v_item->>'quantity')::integer;if v_qty<1 or v_qty>30 then raise exception '餐點數量不正確';end if;select * into v_menu from public.menu_items where id=(v_item->>'menu_item_id')::uuid and restaurant_id=p_restaurant_id and is_available;if not found then raise exception '部分餐點已停售';end if;v_total:=v_total+v_menu.price*v_qty;end loop;
 insert into public.orders(user_id,restaurant_id,total_amount,note) values(v_user,p_restaurant_id,v_total,coalesce(p_note,'')) returning id into v_order;for v_item in select * from jsonb_array_elements(p_items) loop v_qty:=(v_item->>'quantity')::integer;select * into v_menu from public.menu_items where id=(v_item->>'menu_item_id')::uuid;insert into public.order_items(order_id,menu_item_id,item_name,unit_price,quantity) values(v_order,v_menu.id,v_menu.name,v_menu.price,v_qty);end loop;return v_order;end;$$;
revoke all on function public.create_order(uuid,jsonb,text) from public;grant execute on function public.create_order(uuid,jsonb,text) to authenticated;
create or replace function public.merchant_update_order_status(p_order_id uuid,p_status text) returns void language plpgsql security definer set search_path=public as $$begin if p_status not in('accepted','preparing','ready','completed','cancelled') then raise exception '不合法的訂單狀態';end if;update public.orders o set status=p_status where o.id=p_order_id and exists(select 1 from public.restaurants r where r.id=o.restaurant_id and r.owner_id=auth.uid());if not found then raise exception '找不到訂單或沒有權限';end if;end;$$;
revoke all on function public.merchant_update_order_status(uuid,text) from public;grant execute on function public.merchant_update_order_status(uuid,text) to authenticated;
